import {statisticsRows,awardRanking,AWARD_NAMES} from './statistics.js?v=3.7.0';
import {orderedOffers,PREFERENCES} from './career-plan.js?v=3.7.0';
import {hero,team,overall} from './engine.js?v=3.7.0';
import {leagueDef} from './leagues.js?v=3.7.0';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(text,action,disabled=false)=>`<button class="link" data-action="${esc(action)}" ${disabled?'disabled':''}>${esc(text)}</button>`;
const options=(values,value)=>values.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('');
const yearOptions=s=>[[s.season,'Saison actuelle · '+s.season],...s.archives.map(a=>[a.season,'Saison '+a.season]).reverse()];
const average=(st,k)=>st.gp?(st[k]/st.gp).toFixed(1):'—';
const shot=(st,m,a)=>`${st[a]?(100*st[m]/st[a]).toFixed(1)+' %':'—'} <small>(${st[m]}/${st[a]})</small>`;
export function statsView(s,league,f){
 const season=f.season||s.season,data=statisticsRows(s,{...f,season,league});
 const offset=Math.min((f.page||0)*40,Math.max(0,Math.floor((data.rows.length-1)/40)*40)),rows=data.rows.slice(offset,offset+40),mine=data.rows.find(r=>r.id===s.hero);
 if(mine&&!rows.includes(mine))rows.unshift(mine);
 return `<div class="v34-statistics"><h3>Le détail d’une saison</h3><div class="filter-grid"><label>Saison<select id="stats-season">${options(yearOptions(s),season)}</select></label><label>Phase<select id="stats-phase">${options([['regular','Saison régulière'],['playin','Play-in'],['post','Playoffs'],['all','Toutes phases · total'],['unknown','Anciennes données non ventilées']],f.phase)}</select></label><label>Club<select id="stats-club">${options([['all','Tous les clubs'],...s.teams.filter(t=>t.competitions.includes(league)).map(t=>[t.id,t.name])],f.team)}</select></label><label>Classer par<select id="stats-sort">${options([['pts','Points / match'],['reb','Rebonds / match'],['ast','Passes / match'],['stl','Interceptions / match'],['blk','Contres / match'],['tov','Pertes / match'],['min','Minutes / match'],['gp','Matchs joués'],['fg','Réussite aux tirs'],['three','Réussite à 3 points'],['free','Réussite aux lancers'],['name','Nom']],f.sort)}</select></label><label>Ordre<select id="stats-direction">${options([['desc','Décroissant'],['asc','Croissant']],f.direction)}</select></label><label>Joueur<input type="search" id="stats-query" value="${esc(f.query)}" placeholder="Nom du joueur"></label></div>
 <p class="muted">${data.rows.length} joueurs · Moyennes par match. Les tirs indiquent le pourcentage et le volume total. Votre ligne reste épinglée sur chaque page lorsqu’elle correspond aux filtres.</p>
 ${data.partial?'<p class="data-note">Suivi partiel : seules les phases et les équipes prouvées sont attribuées. Les autres totaux restent dans « Anciennes données non ventilées ». Aucun résultat passé n’est inventé.</p>':''}
 ${data.unavailable?'<p>Le détail par phase de cette ancienne saison est indisponible. Ses totaux conservés restent dans les bilans de carrière.</p>':`<div class="table-scroll" tabindex="0" aria-label="Statistiques, défilement horizontal"><table><thead><tr>${['Joueur','MJ','MIN','PTS','REB','PD','INT','CTR','BP','Tirs','3 PTS','LF'].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr class="${r.id===s.hero?'you':''}"><td>${button(r.name+(r.id===s.hero?' · VOUS':''),'profile:'+r.id)}<small>${r.teams.map(id=>esc(team(s,id)?.name)).join(' / ')||'Club non attribué'}</small></td><td>${r.stats.gp}</td>${['min','pts','reb','ast','stl','blk','tov'].map(k=>`<td>${average(r.stats,k)}</td>`).join('')}<td>${shot(r.stats,'fgm','fga')}</td><td>${shot(r.stats,'tpm','tpa')}</td><td>${shot(r.stats,'ftm','fta')}</td></tr>`).join('')||'<tr><td colspan="12">Aucun match enregistré pour ces filtres.</td></tr>'}</tbody></table></div><div class="button-row">${button('← Page précédente','stats-prev',offset===0)}<span>${offset+1}–${Math.min(offset+40,data.rows.length)} / ${data.rows.length}</span>${button('Page suivante →','stats-next',offset+40>=data.rows.length)}</div>`}</div>`;
}
export function profileView(s,id){
 const live=s.players.find(p=>p.id===id),q=s.statistics.people[id]||s.world.people[id];
 if(!q)return '<section class="panel"><p>Dossier indisponible pour cette identité ancienne.</p></section>';
 const awards=s.statistics.awards.filter(a=>a.winners.some(p=>p.id===id)),years=q.years||[],total=years.reduce((a,y)=>{for(const k of ['gp','pts','reb','ast'])a[k]+=y.stats[k]||0;return a;},{gp:0,pts:0,reb:0,ast:0});
 if(live)for(const k of Object.keys(total))total[k]+=live.season[k]||0;
 const club=s.teams.find(t=>t.roster.includes(id));
 return `<section class="panel player-dossier" tabindex="-1"><div class="section-title"><h2>${esc(q.name)}</h2>${button('Fermer le dossier','close-profile')}</div><p>${esc(q.pos)} · ${live?live.age+' ans · '+overall(live)+' de général':s.world.retired.some(p=>p.id===id)?'Retraité':'Ancien joueur ou hors effectif actif'} · ${esc(club?.name||'Archives')}</p><p class="muted">Identité conservée · suivi détaillé depuis la saison ${q.firstTracked||'inconnue'}${q.priorUnknown?' ; carrière antérieure partiellement connue':''}.</p>
 <div class="stat-strip">${[['MJ',total.gp],['Points',total.pts],['Rebonds',total.reb],['Passes',total.ast]].map(([l,v])=>`<div><strong>${Math.round(v).toLocaleString('fr-FR')}</strong><span>${l} · période suivie</span></div>`).join('')}</div>
 <h3>Saisons et clubs</h3>${years.map(y=>`<div class="fixture"><b>S${y.season}</b><span>${y.teams.map(id=>esc(team(s,id)?.name)).join(' → ')||'Club non attribué'}${y.partial?' · suivi partiel':''}<br>${y.stats.gp} matchs · ${average(y.stats,'pts')} PTS · ${average(y.stats,'reb')} REB · ${average(y.stats,'ast')} PD</span></div>`).join('')||'<p>Le premier bilan détaillé sera conservé en fin de saison.</p>'}
 ${live?.season.gp?`<p>Saison actuelle : ${live.season.gp} matchs · ${average(live.season,'pts')} points · ${average(live.season,'reb')} rebonds · ${average(live.season,'ast')} passes.</p>`:''}
 <details><summary>Records et blessures importantes</summary>${Object.entries(q.records||{}).map(([k,r])=>`<p>${{pts:'Points',reb:'Rebonds',ast:'Passes',stl:'Interceptions',blk:'Contres'}[k]} : <b>${r.value}</b> · S${r.season}${r.opponent?' face à '+esc(team(s,r.opponent)?.name):''}</p>`).join('')||'<p>Records détaillés indisponibles.</p>'}${(q.injuries||[]).map(i=>`<p>S${i.season} · blessure : ${i.days} jours estimés à l’annonce.</p>`).join('')||'<p>Aucune blessure importante enregistrée pendant le suivi.</p>'}</details>
 <details><summary>Titres et distinctions conservés</summary>${(q.titles||[]).map(t=>`<p>Champion ${esc(leagueDef(t.league).name)} · S${t.season} · ${esc(team(s,t.team)?.name)}</p>`).join('')}${awards.map(a=>`<p>${esc(AWARD_NAMES[a.kind])} ${esc(leagueDef(a.league).name)} · S${a.season}</p>`).join('')||'<p>Aucune distinction individuelle enregistrée.</p>'}</details>
 ${s.legacy.rivals.filter(r=>r.leader?.id===id).map(r=>`<p>Dernière confrontation mémorisée : ${esc(q.name)} a inscrit ${r.leader.pts} points pour ${esc(r.name)}. Votre bilan collectif face à ce club : ${r.wins}–${r.gp-r.wins}.</p>`).join('')}</section>`;
}
export function directoryView(s,query=''){
 const rows=Object.values(s.statistics.people).filter(p=>!query||p.name.toLocaleLowerCase().includes(query.toLocaleLowerCase())).sort((a,b)=>a.name.localeCompare(b.name)).slice(0,40);
 return `<h3>Dossiers des joueurs</h3><label>Rechercher un joueur actuel ou ancien<input id="directory-query" type="search" value="${esc(query)}" placeholder="Nom"></label><p class="muted">Identités conservées depuis le début du suivi. Affichage limité à 40 noms : affinez votre recherche.</p><div class="directory">${rows.map(p=>button(p.name+' · '+p.pos,'profile:'+p.id)).join('')}</div>`;
}
export function awardsView(s,league,f){
 const year=Number(f.season||s.season),kind=f.kind||'mvp',closed=s.statistics.awards.find(a=>a.season===year&&a.league===league&&a.kind===kind),live=year===s.season&&!closed?awardRanking(s,league,kind==='team'?'mvp':kind):null,rows=closed?.candidates||live?.candidates.slice(0,10)||[];
 return `<div class="awards-view"><h3>Distinctions et course aux trophées</h3><div class="filter-grid"><label>Saison<select id="awards-season">${options(yearOptions(s),year)}</select></label><label>Distinction<select id="awards-kind">${options(Object.entries(AWARD_NAMES),kind)}</select></label></div><p class="muted">${kind==='finals'?'Uniquement les matchs de la finale : au moins la moitié jouée, avec au moins 20 % du temps réglementaire en moyenne, dans l’équipe championne.':'Saison régulière uniquement : au moins 60 % des matchs du calendrier et 20 % du temps réglementaire en moyenne. Le statut de rookie doit être établi.'} Les équipes de la saison comprennent deux arrières, deux ailiers et un pivot.</p>
 ${closed?`<h4>${closed.winners.length?closed.winners.map(p=>esc(p.name)).join(' · '):'Non attribué · données ou éligibilité insuffisantes'}</h4>`:'<p class="data-note">Course provisoire : l’éligibilité se construit pendant la saison. Aucun trophée n’est encore attribué.</p>'}
 ${(closed?.unavailable||live?.unavailable)?'<p class="data-note">Cette saison contient des données anciennes non ventilées. Les nouvelles distinctions ne seront pas attribuées sur une comparaison incomplète.</p>':''}
 <div class="award-candidates">${rows.map((r,i)=>`<article><b>${i+1}. ${button(r.name,'profile:'+r.id)}</b><p>${r.eligible?'Éligible':'Non éligible · '+esc(r.reason)} · indice ${r.score.toFixed(1)}</p><p class="muted">${r.stats.gp} matchs · ${average(r.stats,'pts')} PTS · ${average(r.stats,'reb')} REB · ${average(r.stats,'ast')} PD · efficacité vraie ${(r.components.ts*100).toFixed(1)} % · participation ${(r.components.participation*100).toFixed(0)} %</p></article>`).join('')||'<p>Aucune candidature conservée pour cette sélection.</p>'}</div>
 <details><summary>Comment le classement est calculé</summary><p>Production ramenée à 36 minutes, avec un minimum de 18 minutes par match au dénominateur : 0,55 × points + 1,2 × passes + 0,7 × rebonds + 2 × interceptions + 2 × contres − 1,5 × pertes. Pondération de présence : 65 % + 35 % × part du calendrier jouée ; bonus d’efficacité vraie borné à ±4 et jusqu’à 3 points pour les victoires.</p><p>Défense : 2,5 × interceptions + 2,5 × contres + 0,3 × rebonds défensifs, ramenés à 36 minutes, pondérés par la présence, plus jusqu’à 2 points collectifs. C’est une estimation fondée sur les actions enregistrées. Les détails défensifs non simulés n’entrent pas dans le classement. Égalités départagées par identifiant stable.</p></details></div>`;
}
export function coachPanel(s){
 const e=s.careerPlan.evaluation,r=s.careerPlan.reviews.at(-1);
 return `<section class="panel coach-panel"><h3>Le point avec votre coach</h3>${e?`<p><b>Évaluation en cours · J${e.start} à J${e.due}</b></p><p>${e.gp}/${e.targetGames} matchs minimum · moyenne ${e.gp?(e.grades/e.gp).toFixed(1):'—'}/${e.targetGrade} attendus. ${e.extended?'Délai prolongé après blessure.':''}</p>`:`<p>${esc(s.roleReason||'Votre niveau, vos performances et la concurrence déterminent votre place.')}</p>${button('Demander davantage de responsabilités','role-request',s.retired||!!s.pending||!!s.match||s.day-(s.lastRoleRequest??-100)<21)}`}${r?`<details><summary>Dernier bilan · ${esc(r.outcome)}</summary><p>${esc(r.text)}</p></details>`:''}</section>`;
}
export function marketOffersView(s){return `<label>Ma priorité<select id="market-preference">${options(Object.entries(PREFERENCES),s.careerPlan.preference)}</select></label><div class="offers comparison-offers">${orderedOffers(s).map(({o,index,c})=>`<article><p class="eyebrow">${esc(leagueDef(o.league).name)}</p><h3>${esc(team(s,o.team).name)}</h3><strong>${o.academic?'Place au programme':Math.round(o.salary).toLocaleString('fr-FR')+' € / an'}</strong><p>${esc(o.role)} · ${c.minutes.join('–')} min estimées · ${o.years} an(s)</p><p>Projet : <b>${esc(c.project)}</b> · huit meilleurs coéquipiers : ${c.strength} de général.<br>Concurrence : rang estimé ${c.rank} au poste.</p><p class="muted">${c.rivals.map(p=>esc(p.name)+' ('+p.ovr+')').join(' · ')||'Aucun concurrent direct au poste.'}</p><p class="muted">Système ${c.sameSystem?'similaire':'différent'} : ${c.retention} % de maîtrise conservée si vous changez de club. Temps de jeu réévalué par le coach.</p>${button(o.academic?'Choisir cette université':'Signer ce contrat','sign:'+index)}</article>`).join('')}</div>`;}
export function chaptersPanel(s){
 const y=s.chapters.current;return `<section class="panel chapters-panel"><p class="eyebrow">LES ENJEUX DE VOTRE SAISON</p><h3>La suite de votre histoire</h3><div class="chapter-grid">${y.entries.map(e=>`<article><h4>${esc(e.title)}</h4><p>${esc(e.text)}</p><b>${e.completed!==null?'Accompli ✓':Math.min(e.value,e.target).toLocaleString('fr-FR')+' / '+e.target.toLocaleString('fr-FR')}</b></article>`).join('')}</div><p class="muted">Ces chapitres suivent vos matchs, vos clubs et vos adversaires. Ils n’accordent aucun bonus de puissance.</p>${s.chapters.history.length?`<details><summary>Chapitres précédents</summary>${s.chapters.history.slice(-10).reverse().map(y=>`<p><b>Saison ${y.season}</b> · ${y.entries.map(e=>esc(e.title)+(e.completed!==null?' ✓':' — non accompli')).join(' · ')}</p>`).join('')}</details>`:''}</section>`;
}
